using Microsoft.EntityFrameworkCore;
class ProductContext : DbContext
{
    public DbSet<Product> Products => Set<Product>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // EF Core 9 breaking change #1: Discriminator property renamed from
        // "Discriminator" to "$type". Revert to old name so existing 500K
        // documents (and direct SQL queries referencing c.Discriminator) still work.
        modelBuilder.Entity<Product>().HasDiscriminatorInJsonProperty("Discriminator");

        // EF Core 9 breaking change #2: Id values no longer include the
        // discriminator prefix. EF8 wrote "Product|123"; EF9 defaults to "123".
        // Opt in to the legacy format so existing documents are found by key.
        modelBuilder.Entity<Product>().HasIdProperty(p => p.Id)
            .HasIdPrefixDiscriminator();

        modelBuilder.Entity<Product>().ToContainer("Products");

        // Breaking change #3: HasIndex() now throws for Cosmos — removed.
    }
}
class Product { public int Id { get; set; } public string Sku { get; set; } }

